import{_ as i,l as s,o as e,c as o,v as r,p as l,x as t,d,i as N,S as p}from"./chunks/framework.InCnrqk-.js";const O=JSON.parse('{"title":"与或非与万能门","description":"","frontmatter":{"title":"与或非与万能门","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nand-universal.md","filePath":"cs/nand-universal.md","lastUpdated":1789023840000}'),h={name:"cs/nand-universal.md"};function c(A,a,D,E,_,m){const n=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="与或非与万能门" tabindex="-1">与或非与万能门 <a class="header-anchor" href="#与或非与万能门" aria-label="Permalink to &quot;与或非与万能门&quot;">​</a></h1><div class="epigraph"><p>与非单独就能拼出与、或、非；因此一片只烧与非的阵列在功能上已经完备。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Shannon, 1938 整理</footer></div><p>上一课<a href="/cs/cmos-inverter">CMOS 反相器</a>钉死了非的硅实现。本课不重画转移曲线，也不从布尔公理再证一遍交换律。<a href="/cs/cmos-inverter">布尔代数</a>已有与或非；缺口是：<strong>哪些门集合能实现全部布尔函数</strong>，以及 CMOS 上与非为何是自然的万能门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>反相器只有一输入。任意 \\(n\\) 元函数需要能表达与、或、非中的全体——上一课布尔已证三者完备。缺口是实现：CMOS 把串联 nMOS、并联 pMOS 做成与非，对偶做成或非，比「与再加非」少一级。NAND（或 NOR）单独完备：\\(\\bar x = x\\,\\mathrm{NAND}\\,x\\)，与、或由此拼出。</p><p>本课只钉功能完备与 CMOS 复合物。延迟、负载是<a href="/cs/gate-delay">下一课</a>。AOI 复合门点到为止。</p><h3 id="万能不是「延迟最短」" tabindex="-1">万能不是「延迟最短」 <a class="header-anchor" href="#万能不是「延迟最短」" aria-label="Permalink to &quot;万能不是「延迟最短」&quot;">​</a></h3><p>NAND 万能指功能，不指时序最优。全用 NAND 的网表往往更深。后课综合会混用。把「FPGA 基本单元」提前成 NAND 也不对：LUT 是另一层，本课不讲可编程结构。</p><p><span class="marginnote">Harris 给出 CMOS NAND/NOR 的管级串联并联。De Morgan 在器件上就是把气泡挪到另一边。本课不把晶体管尺寸比写成模拟作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CMOS NAND2：两个 nMOS 串联接地，两个 pMOS 并联上拉。输出低仅当两输入都高。NOR 对偶。用 NAND 构造 NOT、AND、OR 的等式按布尔课改写，不再列公理。</p>',11)),(e(),l(p,null,{default:t(()=>[N(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22CMOS%20%E9%9D%9E%22%5D%20--%3E%20NAND%5B%22CMOS%20%E4%B8%8E%E9%9D%9E%22%5D%0A%20%20NAND%20--%3E%20UNIV%5B%22%7BNAND%7D%20%E5%8A%9F%E8%83%BD%E5%AE%8C%E5%A4%87%22%5D%0A%20%20UNIV%20--%3E%20NET%5B%22%E4%BB%BB%E6%84%8F%E7%BB%84%E5%90%88%E7%BD%91%E8%A1%A8%22%5D%0A%20%20NET%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了万能门，任意规范 SOP 都能映射成门网：与项用 NAND-NAND 或 AND-OR。PLA、标准单元库以 NAND/NOR/AOI 为砖。纠错码的异或是与或非的组合，本课不把门级 XOR 展开成晶体管数竞赛。</p><p>扇入增大则串联堆叠变慢、噪声容限变差，这是延迟课的入口；本课只承认堆叠合法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入传输管逻辑、多米诺动态逻辑。不把功能完备与图灵完备混名：这里没有状态、没有无限带。时钟仍未出现。</p><p>后课默认：组合功能可全用 NAND 或全用 NOR 实现；CMOS 静态门是互补上拉下拉网络。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CMOS 与非/或非是互补串并联；NAND 或 NOR 单独万能。</li><li>万能是功能完备，不是延迟或面积最优。</li><li>任意布尔函数可落地为门网；代价由后课时延计量。</li><li>出处：Harris and Harris；Shannon, 1938。</li></ul>',8))])}const S=i(h,[["render",c]]);export{O as __pageData,S as default};
